{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What is 12mm in inches?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "12mm equals exactly 0.4724409 inches in decimal format. When converted to standard shop fractional measurements, 12mm is approximately 15/32 of an inch (0.46875 inches), with a difference of only 0.0037 inches (0.094mm)."
      }
    },
    {
      "@type": "Question",
      "name": "Is 12mm the same as half an inch?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No, 12mm is not the same as half an inch. A half-inch equals exactly 12.70 millimeters (0.5000 inches). Therefore, 12mm is 0.70 millimeters (0.0276 inches) smaller than a half-inch. While 0.7mm seems minor visually, it creates enough clearance slop to round off bolt heads if a 1/2-inch socket is used on a 12mm fastener."
      }
    },
    {
      "@type": "Question",
      "name": "Can I use a 1/2-inch wrench or socket on a 12mm bolt?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "You should not use a 1/2-inch socket or wrench on a 12mm bolt. The 0.7mm loose fit allows the socket to rotate across the flats and focus all torque pressure directly onto the sharp corners of the bolt head. Under moderate to heavy torque, this strips and rounds off the bolt head. Always use a dedicated 6-point 12mm socket for metric fasteners."
      }
    },
    {
      "@type": "Question",
      "name": "What is the closest fractional imperial wrench size to 12mm?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The closest fractional imperial wrench size to 12mm is 15/32 inch (11.906mm). However, because 12mm is 0.094mm larger than 15/32 inch, a 15/32-inch wrench will generally not slide onto a 12mm hex head unless the bolt is undersized. In practice, 15/32 inch is also a rare tool size, which is why metric sockets are essential."
      }
    },
    {
      "@type": "Question",
      "name": "Why are 12mm bolts so common on Japanese vehicles?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Japanese vehicles from manufacturers like Toyota, Honda, Nissan, and Subaru follow the Japanese Industrial Standard (JIS B 1180), which specifies a 12mm hex head for standard M8 bolts. In contrast, European manufacturers following DIN or ISO standards use a 13mm hex head for M8 bolts. Japanese engineers selected 12mm to reduce weight, save material, and maximize compact clearances."
      }
    },
    {
      "@type": "Question",
      "name": "What is 12mm plywood thickness in imperial measurements?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "12mm plywood equals approximately 0.472 inches thick. While often sold or referenced nominally as half-inch plywood in North American lumberyards, it is noticeably thinner than a true 0.500-inch board. Cabinetmakers must use dedicated 12mm or undersized 15/32-inch router bits to cut snug dado joints that hold shelves securely."
      }
    },
    {
      "@type": "Question",
      "name": "What is a 12mm camera lens equivalent to on different sensor sizes?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "On a 35mm full frame sensor, a 12mm lens is an ultra-wide optic with a 122-degree diagonal field of view. On an APS-C sensor with a 1.5x crop factor, it delivers a field of view equivalent to an 18mm full frame lens. On a Micro Four Thirds sensor with a 2.0x crop factor, it functions as a 24mm standard wide-angle lens."
      }
    },
    {
      "@type": "Question",
      "name": "How do you convert millimeters to inches manually?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "To convert millimeters to inches manually, divide your millimeter measurement by 25.4. For example, for 12mm: 12 divided by 25.4 equals 0.47244 inches. Alternatively, you can multiply millimeters by 0.03937 to achieve the same result."
      }
    }
  ]
}
